import os
import torch


class Config:
    """
    Global configuration for the Parallel Low-Rank DCN-ResNet experiment.
    Encapsulates file paths, feature definitions, model architecture, and training hyperparameters.
    """

    # ==========================================
    # 1. File Paths & Directories
    # ==========================================
    # Metadata paths (generated by previous steps)
    METADATA_DIR = "./metadata"
    TRAIN_DATA_PATH = os.path.join(METADATA_DIR, "train.parquet")
    VAL_DATA_PATH = os.path.join(METADATA_DIR, "val.parquet")
    TEST_DATA_PATH = os.path.join(METADATA_DIR, "test.parquet")

    # Input paths
    INPUT_DIR = "./input"
    SAMPLE_SUBMISSION_PATH = os.path.join(INPUT_DIR, "sample_submission.csv")

    # Working directory for caching and artifacts
    WORKING_DIR = "./working/idea_13"
    CACHE_DIR = WORKING_DIR
    MODEL_SAVE_PATH = os.path.join(WORKING_DIR, "parallel_low_rank_dcn_resnet.pth")

    # Submission directory
    SUBMISSION_DIR = "./submission"
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # ==========================================
    # 2. Global Hyperparameters
    # ==========================================
    SEED = 42
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"
    NUM_WORKERS = 4  # Number of dataloader workers

    # ==========================================
    # 3. Data Configuration
    # ==========================================
    TARGET_COL = "Cover_Type"
    ID_COL = "Id"

    # Raw Continuous Features (from dataset analysis)
    RAW_CONT_FEATURES = [
        "Elevation",
        "Aspect",
        "Slope",
        "Horizontal_Distance_To_Hydrology",
        "Vertical_Distance_To_Hydrology",
        "Horizontal_Distance_To_Roadways",
        "Horizontal_Distance_To_Fire_Points",
        "Hillshade_9am",
        "Hillshade_Noon",
        "Hillshade_3pm",
    ]

    # Raw Binary Features
    # Wilderness_Area (4) + Soil_Type (40)
    RAW_BINARY_FEATURES = [f"Wilderness_Area{i}" for i in range(1, 5)] + [
        f"Soil_Type{i}" for i in range(1, 41)
    ]

    # Engineered Features (to be created in preprocessing)
    # Strategy: Augmented Physics-Informed Engineering
    ENGINEERED_CONT_FEATURES = [
        "Aspect_Sin",
        "Aspect_Cos",  # Cyclical Augmentation
        "Euclidean_Distance_To_Hydrology",  # Geometric Magnitude
        "Abs_Hydrology_Elevation",  # Directional Preservation
        "Mean_Amenities_Dist",  # Global Context
    ]

    # Final Feature Groups for Model Input
    # The model expects a dense vector of: [Standardized(Raw Cont + Engineered Cont), Raw Binary]
    CONT_FEATURES = RAW_CONT_FEATURES + ENGINEERED_CONT_FEATURES
    BINARY_FEATURES = RAW_BINARY_FEATURES

    # Input Dimension Calculation
    # 10 raw cont + 5 engineered cont = 15 continuous
    # 4 wilderness + 40 soil = 44 binary
    # Total Input Dim = 59
    INPUT_DIM = len(CONT_FEATURES) + len(BINARY_FEATURES)

    # Number of classes for classification
    # Classes are 1-7 (with some potentially missing). We map 1-7 -> 0-6 or use 7 output logits.
    NUM_CLASSES = 7

    # ==========================================
    # 4. Model Architecture Hyperparameters
    # ==========================================
    # Strategy: Parallel Low-Rank DCN-ResNet

    # Branch 1: Low-Rank DCN
    DCN_RANK = 16  # Rank r for U and V decomposition (Structural Innovation)
    DCN_LAYERS = 3  # Number of cross layers

    # Branch 2: Wide ResNet
    RESNET_WIDTH = 512  # Hidden dimension width (Deep Implicit Features)
    RESNET_DEPTH = 2  # Number of residual blocks
    RESNET_DROPOUT = 0.2

    # ==========================================
    # 5. Training Hyperparameters
    # ==========================================
    # Strategy: Budget-Corrected Supervised Optimization
    BATCH_SIZE = 4096
    EPOCHS = 60
    LEARNING_RATE = 1e-3

    # Scheduler (ReduceLROnPlateau)
    SCHEDULER_FACTOR = 0.1
    SCHEDULER_PATIENCE = 5

    # Early Stopping
    EARLY_STOPPING_PATIENCE = 10

    @staticmethod
    def setup():
        """Ensure necessary directories exist."""
        os.makedirs(Config.WORKING_DIR, exist_ok=True)
        os.makedirs(Config.SUBMISSION_DIR, exist_ok=True)


# Run setup immediately when imported
Config.setup()
